create schema if not exists private;
revoke all on schema private from public;
create table private.allowed_emails (email text primary key, admin boolean not null default false);
create table public.members (user_id uuid primary key references auth.users(id) on delete cascade, admin boolean not null default false);
create table public.feature_flags (name text primary key, enabled boolean not null default false);
insert into public.feature_flags values ('personal_travel', true);
create table public.travel_times (user_id uuid references auth.users(id) on delete cascade, spot_id text not null, minutes integer not null check(minutes>0), primary key(user_id,spot_id));
create table public.surf_profiles (user_id uuid primary key references auth.users(id) on delete cascade, preferences jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.surf_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, surf_date date not null, spot_id text not null, starts_at time, kind text not null check(kind in ('planned','surfed')), rating numeric check(rating between 1 and 5), notes text not null default '' check(length(notes)<=3000), recommendation jsonb, created_at timestamptz not null default now(), check(kind='surfed' or rating is null));
create index surf_sessions_owner_date on public.surf_sessions(user_id,surf_date desc);
create table public.forecast_snapshots (user_id uuid not null references auth.users(id) on delete cascade, spot_id text not null, collected_at timestamptz not null default now(), payload jsonb not null, primary key(user_id,spot_id));
create table public.surf_spots (id text primary key, profile jsonb not null, experimental boolean not null default false, provenance text not null);
create function private.is_member() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.members where user_id=(select auth.uid())); $$;
create function private.can_travel() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.members m join auth.users u on u.id=m.user_id join private.allowed_emails a on a.email=lower(u.email) where m.user_id=(select auth.uid()) and m.admin and a.admin) and exists(select 1 from public.feature_flags where name='personal_travel' and enabled); $$;
grant usage on schema private to authenticated;
revoke all on function private.is_member(), private.can_travel() from public,anon;
grant execute on function private.is_member(), private.can_travel() to authenticated;
create function private.on_signup() returns trigger language plpgsql security definer set search_path='' as $$
declare owner_admin boolean;
begin
 select admin into owner_admin from private.allowed_emails where email=lower(new.email);
 if owner_admin is null or new.is_anonymous then raise exception 'Cadastro restrito a convites'; end if;
 insert into public.members(user_id,admin) values(new.id,owner_admin);
 if owner_admin then insert into public.travel_times values(new.id,'mole',35),(new.id,'campeche',25),(new.id,'matadeiro',33),(new.id,'joaquina',35),(new.id,'barra-da-lagoa',41); end if;
 return new;
end; $$;
revoke all on function private.on_signup() from public,anon,authenticated;
create trigger the_search_signup after insert on auth.users for each row execute function private.on_signup();
alter table public.members enable row level security;
alter table public.feature_flags enable row level security;
alter table public.travel_times enable row level security;
alter table public.surf_profiles enable row level security;
alter table public.surf_sessions enable row level security;
alter table public.forecast_snapshots enable row level security;
alter table public.surf_spots enable row level security;
alter table private.allowed_emails enable row level security;
revoke all on all tables in schema public from anon,authenticated;
grant select on public.members,public.feature_flags,public.travel_times,public.surf_spots to authenticated;
grant select,insert,update,delete on public.surf_profiles,public.surf_sessions,public.forecast_snapshots to authenticated;
create policy own_membership on public.members for select to authenticated using(user_id=(select auth.uid()));
create policy flags_members on public.feature_flags for select to authenticated using((select private.is_member()));
create policy travel_owner_admin_flag on public.travel_times for select to authenticated using(user_id=(select auth.uid()) and (select private.can_travel()));
create policy member_spots on public.surf_spots for select to authenticated using((select private.is_member()));
create policy own_profile on public.surf_profiles for all to authenticated using(user_id=(select auth.uid()) and (select private.is_member())) with check(user_id=(select auth.uid()) and (select private.is_member()));
create policy own_sessions on public.surf_sessions for all to authenticated using(user_id=(select auth.uid()) and (select private.is_member())) with check(user_id=(select auth.uid()) and (select private.is_member()));
create policy own_forecasts on public.forecast_snapshots for all to authenticated using(user_id=(select auth.uid()) and (select private.is_member())) with check(user_id=(select auth.uid()) and (select private.is_member()));
